/**
 * extractRowImages — against a REAL .xlsx (`__fixtures__/services-import-with-images.xlsx`,
 * generated by scripts/generate-xlsx-image-fixture.py via openpyxl), not a hand-built mock. Two
 * genuinely different embedded PNGs, one anchored on each of the two data rows.
 */
import { readFileSync } from 'node:fs';
import path from 'node:path';
import { describe, expect, it } from 'vitest';
import { extractRowImages, readXlsxRows } from './xlsx_images';

function loadFixture(): Uint8Array {
  // A Node Buffer, passed as-is (not `.buffer.slice(...)`) — jsdom's `ArrayBuffer` is a
  // DIFFERENT realm's constructor than Node's, so a plain ArrayBuffer built from a Buffer's
  // backing store fails JSZip's own `instanceof` type check under this test environment. A
  // Uint8Array (Buffer already is one) survives the cross-realm check; a real browser caller
  // reading a File via FileReader never has this problem in the first place — one realm only.
  const p = path.join(__dirname, '__fixtures__', 'services-import-with-images.xlsx');
  return readFileSync(p);
}

describe('extractRowImages', () => {
  it('finds exactly two pictures, one per data row', async () => {
    const images = await extractRowImages(loadFixture());
    expect(images).toHaveLength(2);
  });

  it('reports the correct spreadsheet line for each picture (row 2 and row 3)', async () => {
    const images = await extractRowImages(loadFixture());
    const rows = images.map((i) => i.row).sort();
    expect(rows).toEqual([2, 3]);
  });

  it('the two pictures are genuinely different bytes, each on its own row', async () => {
    const images = await extractRowImages(loadFixture());
    const byRow = new Map(images.map((i) => [i.row, i]));
    const row2 = byRow.get(2)!;
    const row3 = byRow.get(3)!;
    expect(row2.base64).not.toBe(row3.base64);
  });

  it('the extracted bytes decode back to real, valid PNG data', async () => {
    const images = await extractRowImages(loadFixture());
    for (const img of images) {
      expect(img.contentType).toBe('image/png');
      const bytes = Uint8Array.from(atob(img.base64), (c) => c.charCodeAt(0));
      // The PNG signature — proof this is real image data, not garbage or a truncated read.
      expect(Array.from(bytes.slice(0, 8))).toEqual([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);
    }
  });

  it('a workbook with no drawing at all returns an empty list, not an error', async () => {
    // A plain xlsx built the same way, minus the images — the common case (most import files
    // never carry a photo at all) must be silent and cheap, never throw.
    const JSZip = (await import('jszip')).default;
    const zip = new JSZip();
    zip.file('xl/worksheets/sheet1.xml', '<worksheet/>');
    zip.file('[Content_Types].xml', '<Types/>');
    const buf: Uint8Array = await zip.generateAsync({ type: 'uint8array' });
    const images = await extractRowImages(buf);
    expect(images).toEqual([]);
  });
});

describe('readXlsxRows', () => {
  it('reads the real header and both real data rows from the fixture', async () => {
    const rows = await readXlsxRows(loadFixture());
    expect(rows).toEqual([
      { name: 'غسيل خارجي', price: '50', duration_minutes: '30', cycle_days: '0',
        external_id: '', description: 'الصف الأول' },
      { name: 'تلميع', price: '80', duration_minutes: '20', cycle_days: '0',
        external_id: '', description: 'الصف الثاني' },
    ]);
  });

  it('a workbook with no sheet data returns an empty list, not an error', async () => {
    const JSZip = (await import('jszip')).default;
    const zip = new JSZip();
    zip.file('xl/worksheets/sheet1.xml', '<worksheet/>');
    const buf: Uint8Array = await zip.generateAsync({ type: 'uint8array' });
    expect(await readXlsxRows(buf)).toEqual([]);
  });
});
